ROOT=pathlib.Path(__file__).resolve().parents[4];R=pathlib.Path('/tmp/scratch_gold/sol');P=R/'round2_packages';dest=ROOT/'model-gating/gold-set/candidates.csv'
rows=list(csv.DictReader(dest.open()));fields=list(rows[0]);idx={x['node']:x for x in json.loads((R/'report_index.json').read_text())+json.loads((R/'round2_remaining_index.json').read_text())if x.get('textpath')};new=[];audit={}
I='computational issues';T='technical failure';A='ambiguous';S='computationally reproducible'
def add(k,source,record,title,doi,year,disc,lang,pkg,size,runtime,st,summary,url,eligible,note,exclude='',conf='medium',claim='yes',data='true',textpath=None):
 z={f:''for f in fields};z.update(cand_id=k,source=source,source_record_id=record,title=title,doi=doi,year=str(year),discipline=disc,language=lang,language_ok='true'if lang in ['R','Python','R; Python']else'unknown',package_url=pkg,package_size_mb=str(size),est_runtime=runtime,data_open=data,provisional_stratum=st,evidence_summary=summary,evidence_url=url,claim_level_evidence=claim,eligible='true'if eligible else'false',exclusion_reason=exclude,screener_confidence=conf,notes=note,round='2');new.append(z)
 if textpath:
  p=pathlib.Path(textpath);pdf=pathlib.Path(str(p)[:-4])if str(p).endswith('.pdf.txt')else p;audit[k]=dict(evidence_url=url,textpath=str(p),source_sha256=hashlib.sha256(pdf.read_bytes()).hexdigest())
 return z
def add_note_first(*args, **kwargs):
 q=list(args);q[13],q[14],q[15]=q[14],q[15],q[13];return add(*q,**kwargs)
def i4r(node,doi,year,disc,lang,pkg,size,st,summary,note,eligible=False,exclude='',runtime='not established within 2 h',data='unknown'):
 x=idx[node];return add('I4R-'+node,'I4R',node,x['title'],doi,year,disc,lang,pkg,size,runtime,st,summary,x['evidence_url'],eligible,note,exclude=exclude,data=data,textpath=x['textpath'])
